package com.alpharip.staffmod.IncidentPostMortemBoard; public final class IncidentImpact { private String affectedSystems,affectedUsers,description; private int severity; private long assessedAt; public IncidentImpact(){} public IncidentImpact(String s,String u,String d,int v,long t){affectedSystems=clean(s);affectedUsers=clean(u);description=clean(d);if(v<1||v>5)throw new IllegalArgumentException("Impact severity must be 1-5");if(t<=0)throw new IllegalArgumentException("Timestamp must be positive");severity=v;assessedAt=t;} public String getAffectedSystems(){return affectedSystems;} public String getAffectedUsers(){return affectedUsers;} public String getDescription(){return description;} public int getSeverity(){return severity;} public long getAssessedAt(){return assessedAt;} private static String clean(String s){return s==null?"":s.trim();} }